const state = { user: null, employee: null, settings: {}, page: 'dashboard', cache: {}, payrollRun: null, payrollItems: [] };
const $ = (sel, root=document) => root.querySelector(sel);
const $$ = (sel, root=document) => [...root.querySelectorAll(sel)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials = name => String(name || 'LR').trim().split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase();
const labelize = s => String(s || '').replaceAll('_',' ').replace(/\b\w/g, m=>m.toUpperCase());
const today = () => new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Dhaka',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const nextDhakaDay = () => { const [y,m,d]=today().split('-').map(Number); return new Date(Date.UTC(y,m-1,d+1)).toISOString().slice(0,10); };
const salaryEffectiveDefault = salary => salary?.effective_from===today()?nextDhakaDay():today();
const taskLink = value => /^https?:\/\//i.test(String(value||'')) ? `<a href="${esc(value)}" target="_blank" rel="noopener noreferrer">Open link</a>` : esc(value||'—');
const money = n => '৳' + Number(n || 0).toLocaleString('en-BD',{maximumFractionDigits:2});
// All duration values are decimal hours from minute-based server calculations.
 // Convert back to whole minutes for human-readable, unambiguous display.
const hours = n => {
  const totalMinutes = Math.max(0, Math.round(Number(n || 0) * 60));
  const h = Math.floor(totalMinutes / 60);
  const m = totalMinutes % 60;
  if (!h && !m) return '0m';
  if (!m) return `${h}h`;
  if (!h) return `${m}m`;
  return `${h}h ${m}m`;
};
function fileToPayload(file){return new Promise((resolve,reject)=>{if(!file){resolve(null);return;}const reader=new FileReader();reader.onload=()=>resolve({name:file.name,type:file.type,data:reader.result});reader.onerror=()=>reject(new Error('Could not read the selected file'));reader.readAsDataURL(file);});}
function applyBranding(){const title=state.settings.system_name||'Light Retouch Management System';document.title=title;const brand=$('.sidebar-brand strong');if(brand)brand.textContent=title;const sub=$('.sidebar-brand span');if(sub)sub.textContent='MANAGEMENT SYSTEM';const foot=$('.app-footer span:first-child');if(foot)foot.textContent=(state.settings.company_name||'Light Retouch')+' · '+title;const loginTitle=$('#loginSystemName');if(loginTitle)loginTitle.textContent=title;const logoUrl=state.settings.brand_logo?'/brand-logo?v='+encodeURIComponent(state.settings.brand_logo):'';$$('.brand-mark').forEach(el=>{if(logoUrl){el.innerHTML=`<img src="${logoUrl}" alt="Company logo">`;el.classList.add('has-logo');}else{el.textContent='LR';el.classList.remove('has-logo');}});const mobile=$('.mobile-brand span');if(mobile)mobile.textContent=title;const footLogin=$('.login-art-foot');if(footLogin)footLogin.innerHTML=`${esc(state.settings.company_name||'LIGHT RETOUCH')} <span>•</span> INTERNAL MANAGEMENT SYSTEM`;}


async function api(path, options={}) {
  const opts = {...options, headers: {'Content-Type':'application/json', ...(options.headers||{})}};
  if (opts.method && opts.method !== 'GET') opts.headers['X-HRMS-Request'] = '1';
  const response = await fetch(path, opts);
  let data;
  try { data = await response.json(); } catch { data = {error:'The server returned an unreadable response'}; }
  if (!response.ok) {
    if (response.status === 401 && !path.includes('/login')) showLogin();
    throw new Error(data.error || 'Request failed');
  }
  return data;
}
const post = (path, data={}) => api(path,{method:'POST',body:JSON.stringify(data)});

function showLogin(message='') {
  $('#appView').classList.add('hidden');
  $('#loginView').classList.remove('hidden');
  $('#loginError').textContent = message;
  $('#loginError').classList.toggle('hidden',!message);
}
function showApp() { $('#loginView').classList.add('hidden'); $('#appView').classList.remove('hidden'); }
function toast(message,type='success') {
  const el = document.createElement('div'); el.className = `toast ${type}`; el.textContent = message;
  $('#toastRoot').append(el); setTimeout(()=>el.remove(),3800);
}
function statusPill(value) {
  const slug = String(value||'').toLowerCase().replaceAll(' ','-');
  return `<span class="status ${esc(slug)}">${esc(value||'—')}</span>`;
}
function emptyState(title='Nothing here yet', text='Records will appear here when they are added.') {
  return `<div class="empty-state"><div class="empty-icon">◌</div><strong>${esc(title)}</strong><p>${esc(text)}</p></div>`;
}
function pageHeader(title, subtitle, action='') {
  return `<div class="page-heading"><div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="heading-actions">${action}</div></div>`;
}
function tableCard(title, subtitle, headers, rows, extra='') {
  return `<div class="data-card"><div class="data-card-head"><div><h3>${esc(title)}</h3><small>${esc(subtitle||'')}</small></div>${extra}</div>${rows.length ? `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>` : emptyState()}</div>`;
}
function navItems() {
  const role = state.user.role;
  const items = [];
  const add = (section, entries) => { items.push({section}); entries.forEach(e=>items.push(e)); };
  if (role === 'employee') {
    add('MY WORKSPACE', [
      {id:'dashboard',name:'My overview',icon:'⌂'},
      {id:'attendance',name:'My attendance',icon:'◷'},
      {id:'leaves',name:'Leave & holidays',icon:'▤'},
      {id:'my-payslips',name:'My payslips',icon:'৳'},
      {id:'tasks',name:'My production tasks',icon:'✂'},
      {id:'my-profile',name:'My profile & documents',icon:'♙'},
    ]);
  } else if (role === 'manager') {
    add('TEAM MANAGEMENT', [
      {id:'dashboard',name:'Team overview',icon:'⌂'},
      {id:'employees',name:'My team',icon:'♙'},
      {id:'attendance',name:'Team attendance',icon:'◷'},
      {id:'leaves',name:'Leave approvals',icon:'▤'},
      {id:'performance',name:'Performance reviews',icon:'◈'},
      {id:'tasks',name:'Production tasks',icon:'✂'},
      {id:'my-profile',name:'My profile & documents',icon:'♙'},
    ]);
  } else if (role === 'payroll_admin') {
    add('OVERVIEW', [{id:'dashboard',name:'Dashboard',icon:'⌂'}]);
    add('PAYROLL WORKSPACE', [{id:'employees',name:'Employee directory',icon:'♙'},{id:'attendance',name:'Attendance & team hours',icon:'◷'},{id:'payroll',name:'Payroll',icon:'৳'},{id:'my-profile',name:'My profile',icon:'♙'}]);
  } else {
    add('OVERVIEW', [{id:'dashboard',name:'Dashboard',icon:'⌂'}]);
    add('PEOPLE & OPERATIONS', [
      {id:'employees',name:'Employee directory',icon:'♙'},
      {id:'tasks',name:'Production tasks',icon:'✂'},
      {id:'attendance',name:'Attendance',icon:'◷'},
      {id:'leaves',name:'Leave management',icon:'▤'},
      {id:'recruitment',name:'Recruitment',icon:'◎'},
      {id:'performance',name:'Performance',icon:'◈'},
      {id:'relations',name:'Employee relations',icon:'⚑'},
      {id:'assets',name:'Assets',icon:'▣'},
      {id:'exits',name:'Exit management',icon:'⇥'},
      {id:'my-profile',name:'My profile & documents',icon:'♙'},
    ]);
    if (['super_admin','payroll_admin'].includes(role)) add('FINANCE', [{id:'payroll',name:'Payroll',icon:'৳'}]);
    if (['super_admin','hr_admin'].includes(role)) add('ADMINISTRATION', [
      {id:'settings',name:'System settings',icon:'⚙'},
      ...(role==='super_admin'?[{id:'users',name:'User access',icon:'♧'}]:[]),
      {id:'audit',name:'Audit trail',icon:'☷'},
    ]);
  }
  return items;
}
function renderNav() {
  $('#mainNav').innerHTML = navItems().map(item => item.section
    ? `<div class="nav-section">${esc(item.section)}</div>`
    : `<button class="nav-item ${state.page===item.id?'active':''}" data-page="${item.id}"><span class="nav-icon">${item.icon}</span><span>${esc(item.name)}</span></button>`).join('');
  $$('.nav-item').forEach(btn=>btn.addEventListener('click',()=>navigate(btn.dataset.page)));
}
function setUserChrome() {
  const display = state.employee?.full_name || state.user.username;
  $('#sidebarName').textContent = display;
  $('#sidebarRole').textContent = state.user.role_label;
  $('#sidebarAvatar').textContent = initials(display);
  $('#topAvatar').textContent = initials(display);
  if(state.employee?.profile_photo_url){$('#sidebarAvatar').innerHTML=`<img src="${esc(state.employee.profile_photo_url)}" alt="Profile" class="avatar-photo">`;$('#topAvatar').innerHTML=`<img src="${esc(state.employee.profile_photo_url)}" alt="Profile" class="avatar-photo">`;} else {$('#sidebarAvatar').textContent=initials(display);$('#topAvatar').textContent=initials(display);}
  applyBranding();
  $('#todayLabel').textContent = new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Dhaka',weekday:'short',day:'2-digit',month:'short',year:'numeric'}).format(new Date());
}
async function boot() {
  try { state.settings = await api('/api/public-branding'); applyBranding(); } catch {}
  try {
    const data = await api('/api/me');
    state.user = data.user; state.employee = data.employee; state.settings = data.settings||{};
    showApp(); setUserChrome(); renderNav();
    if (state.user.must_change_password) { openChangePassword(true); return; }
    await navigate(state.page);
  } catch { showLogin(); }
}
async function navigate(page) {
  state.page = page; renderNav();
  const names = {'my-profile':'My profile & documents',dashboard:state.user.role==='employee'?'My overview':state.user.role==='manager'?'Team overview':'Dashboard',employees:state.user.role==='manager'?'My team':'Employee directory',tasks:'Production tasks',attendance:'Attendance',leaves:'Leave management',payroll:'Payroll',recruitment:'Recruitment',performance:'Performance management',relations:'Employee relations',assets:'Asset management',exits:'Exit management',settings:'System settings',users:'User access',audit:'Audit trail','my-payslips':'My payslips'};
  $('#breadcrumb').textContent = names[page] || 'Workspace';
  $('#topbarContext').textContent = page==='dashboard'?'Your people operations at a glance':'Manage and review company records';
  $('#pageContent').innerHTML = '<div class="loading">Loading workspace…</div>';
  closeSidebar();
  try {
    const renderers = {
      dashboard:renderDashboard, employees:renderEmployees, tasks:renderTasks, attendance:renderAttendance, leaves:renderLeaves,
      payroll:renderPayroll, recruitment:renderRecruitment, performance:renderPerformance,
      relations:renderRelations, assets:renderAssets, exits:renderExits, settings:renderSettings,
      users:renderUsers, audit:renderAudit, 'my-payslips':renderMyPayslips, 'my-profile':renderMyProfile
    };
    if (!renderers[page]) throw new Error('This section is not available for your account');
    await renderers[page]();
  } catch(err) { $('#pageContent').innerHTML = `<div class="notice warning">${esc(err.message)}</div>`; }
}

