      `<div class="panel"><div class="panel-head"><h3>My production tasks</h3><button class="btn btn-secondary btn-small" id="goTasks">View all</button></div>${(d.my_tasks||[]).length?`<div class="table-wrap"><table><thead><tr><th>Project</th><th>Editing type</th><th>Images</th><th>Status</th></tr></thead><tbody>${d.my_tasks.map(t=>`<tr><td>${esc(t.project_name)}<small style="display:block">${esc(t.task_title)}</small></td><td>${esc(t.editing_type)}</td><td>${esc(t.completed_images||0)} / ${esc(t.image_count)}</td><td>${statusPill(t.assignment_status)}</td></tr>`).join('')}</tbody></table></div>`:emptyState('No production tasks assigned','Your assigned photo-editing jobs will appear here.')}</div>`+`<div class="panel"><div class="panel-head"><h3>Recent leave requests</h3><button class="btn btn-secondary btn-small" id="goLeaves">View leave</button></div>${(d.recent_leaves||[]).length?`<div class="table-wrap"><table><thead><tr><th>Leave type</th><th>Dates</th><th>Days</th><th>Status</th></tr></thead><tbody>${d.recent_leaves.map(l=>`<tr><td>${esc(l.leave_type||'—')}</td><td>${esc(l.start_date)} – ${esc(l.end_date)}</td><td>${l.days}</td><td>${statusPill(l.status)}</td></tr>`).join('')}</tbody></table></div>`:emptyState('No leave requests','Your leave requests will appear here.')}</div>`;
    bindAttendanceActions();
