async function renderAttendance(month=today().slice(0,7)) {
  const isEmployee=state.user.role==='employee';
  const isManager=state.user.role==='manager';
  const canViewPrivateAttendance=state.user.role!=='payroll_admin';
  const [events,corrections,summary,todayDashboard]=await Promise.all([canViewPrivateAttendance?api('/api/attendance?month='+month):Promise.resolve([]),canViewPrivateAttendance?api('/api/attendance/adjustments'):Promise.resolve([]),api('/api/attendance/summary?month='+month),isEmployee?api('/api/dashboard'):Promise.resolve(null)]);
  const people=isEmployee?[]:(state.cache.employees||await api('/api/employees'));
  const empOptions = `<option value="">Select employee</option>`+people.map(e=>`<option value="${e.employee_id}">${esc(e.employee_id)} · ${esc(e.full_name)}</option>`).join('');
  const summaryRows=(summary.employees||[]).map(e=>`<tr><td>${person(e.full_name,e.employee_id)}</td><td>${esc(e.department||'—')}</td><td>${e.present_days}</td><td>${e.late_days===null?'—':e.late_days}</td><td>${e.late_minutes===null?'—':e.late_minutes+' min'}</td><td>${e.absent_days}</td><td>${hours(e.presence_hours)}</td><td>${hours(e.break_hours)}</td><td>${hours(e.duty_hours)}</td><td>${e.shift_configured?hours(e.overtime_hours):'—'}</td><td>${e.shift_configured?'Configured':'Not set'}</td><td>${e.incomplete_punches?statusPill(e.incomplete_punches+' missing'): '—'}</td></tr>`);
  $('#pageContent').innerHTML = pageHeader(isEmployee?'My attendance & team hours':isManager?'Team attendance':'Attendance management','Shared check-in/out state · live sync every 45 seconds · everyone can view the monthly team duty-hours and overtime summary. Private correction reasons and individual documents remain restricted.',isEmployee?'<button class="btn btn-secondary" id="requestCorrection">Request correction</button>':(state.user.role==='manager'||['super_admin','hr_admin','hr_executive'].includes(state.user.role))?'<button class="btn btn-secondary" id="requestCorrection">＋ Log correction</button>':'')+
    `<div class="toolbar"><label class="field" style="display:flex;align-items:center;gap:8px">Summary month <input id="attendanceMonth" type="month" value="${esc(month)}" style="width:150px;height:36px"></label></div>`+
    `<div class="metric-grid">${metric('Employees',summary.totals.employees,'Active / probation / notice','♙')}${metric('Present days',summary.totals.present_days,'All staff combined','✓')}${metric('Late days',summary.totals.late_days,'Configured shift grace rules','◷')}${metric('Absent days',summary.totals.absent_days,'Scheduled days only','!')}${metric('Presence hours',hours(summary.totals.presence_hours),'All staff clocked time','◴')}${metric('Break hours',hours(summary.totals.break_hours),'Configured break time','☕')}${metric('Net duty',hours(summary.totals.duty_hours),'After break deduction','◷')}${metric('Overtime',hours(summary.totals.overtime_hours),'Shift-relative estimate','↗')}</div>`+
    `<div class="notice">Presence hours are calculated from complete check-in/check-out punches. Net duty follows the shift's paid/unpaid break setting. Overtime is time above the assigned net shift duration, and is informational until approved as payable overtime. Shift start/end, break, weekly offs and holidays must be configured for accurate calculations.</div>`+
    tableCard('Office-wide attendance & working hours',`${month} · Read-only summary visible to all signed-in users`,['Employee','Department','Present','Late days','Late minutes','Absent','Presence','Break','Net duty','Overtime','Shift rules','Incomplete'],summaryRows)+
    (isEmployee?attendanceActionMarkup(todayDashboard?.today_events||[]):'')+
    tableCard('Attendance event log',`${month} · Raw punch events available to your authorized role`,['Employee','Event','Server timestamp','Source'],events.map(e=>`<tr><td>${person(e.full_name,e.employee_id)}</td><td>${statusPill(labelize(e.event_type))}</td><td>${esc(formatDateTime(e.event_time))}</td><td>${esc(e.source)}</td></tr>`))+
    tableCard('Attendance correction requests','Reason and decision are visible only to the employee and authorized approvers',['Request','Employee','Work date','Reason','Status','Review'],corrections.map(c=>`<tr><td>${esc(c.request_id)}</td><td>${esc(c.employee_id)}</td><td>${esc(c.work_date)}</td><td>${esc(c.reason)}</td><td>${statusPill(c.status)}</td><td>${!isEmployee&&c.status==='Pending'?`<div class="inline-actions"><button class="btn btn-secondary btn-small" data-adjust="${c.request_id}" data-decision="Approved">Approve</button><button class="btn btn-danger btn-small" data-adjust="${c.request_id}" data-decision="Rejected">Reject</button></div>`:esc(c.review_comment||'—')}</td></tr>`));
  if(isEmployee)bindAttendanceActions();
  $('#attendanceMonth').addEventListener('change',()=>renderAttendance($('#attendanceMonth').value||today().slice(0,7)));
  $('#requestCorrection')?.addEventListener('click',()=>openCorrectionForm(isEmployee?state.user.employee_id:null,empOptions));
  $$('[data-adjust]').forEach(b=>b.addEventListener('click',()=>decideAdjustment(b.dataset.adjust,b.dataset.decision)));
}

let attendancePunchBusy=false;
let attendanceRefreshBusy=false;
let attendanceChannel=null;
try{
  if('BroadcastChannel' in window){
    attendanceChannel=new BroadcastChannel('light-retouch-attendance');
    attendanceChannel.addEventListener('message',()=>refreshVisibleAttendance(true));
  }
}catch{}
async function refreshVisibleAttendance(silent=false){
  if(!state.user||attendanceRefreshBusy||!['dashboard','attendance'].includes(state.page))return;
  attendanceRefreshBusy=true;
  try{
    if(state.page==='dashboard')await renderDashboard();
    else await renderAttendance($('#attendanceMonth')?.value||today().slice(0,7));
  }catch(e){if(!silent)toast(e.message,'error');}
  finally{attendanceRefreshBusy=false;}
}
async function punch(eventType){
  if(attendancePunchBusy)return;
  attendancePunchBusy=true;
  $$('[data-attendance-action]').forEach(btn=>btn.disabled=true);
  try{
    await post('/api/attendance/punch',{event_type:eventType});
    toast(eventType==='CHECK_IN'?'Check-in recorded':'Check-out recorded');
    try{attendanceChannel?.postMessage({type:'attendance-changed',at:Date.now()});}catch{}
    await refreshVisibleAttendance(true);
  }catch(e){
    toast(e.message,'error');
    await refreshVisibleAttendance(true);
  }finally{attendancePunchBusy=false;}
}
async function renderDashboardIfHome(){if(state.page==='dashboard')await renderDashboard();}
window.addEventListener('focus',()=>{if(document.visibilityState==='visible')refreshVisibleAttendance(true);});
setInterval(()=>{if(document.visibilityState==='visible')refreshVisibleAttendance(true);},45000);
