async function renderLeaves() {
  const role=state.user.role; const isEmployee=role==='employee'; const isManager=role==='manager';
  const [leaves,types,holidays]=await Promise.all([api('/api/leaves'),api('/api/leave-types'),api('/api/holidays')]);
  const people=isEmployee?[]:(state.cache.employees||await api('/api/employees'));
  const empOptions='<option value="">Select employee</option>'+people.map(e=>`<option value="${e.employee_id}">${esc(e.employee_id)} · ${esc(e.full_name)}</option>`).join('');
  $('#pageContent').innerHTML=pageHeader(isEmployee?'Leave & holidays':isManager?'Leave approvals':'Leave management','Submit requests, review approvals and maintain the company holiday calendar.',`${isEmployee?'<button class="btn btn-primary" id="applyLeave">＋ Apply for leave</button>':role==='super_admin'||role==='hr_admin'||role==='hr_executive'?'<button class="btn btn-secondary" id="addLeaveType">＋ Leave type</button><button class="btn btn-secondary" id="addHoliday">＋ Add holiday</button>':''}`)+
    `<div class="notice">Leave duration currently counts calendar days and excludes published company holidays. Configure each employee’s weekly-off/shift pattern and verify entitlement before approving or deducting any balance. No leave balance is automatically reduced in this version.</div>`+
    tableCard(isEmployee?'My leave requests':'Leave requests',`${leaves.length} request record${leaves.length===1?'':'s'}`,['Request','Employee','Leave type','Period','Days','Attachment','Status','Actions'],leaves.map(l=>`<tr><td>${esc(l.request_id)}</td><td>${esc(l.full_name||l.employee_id)}</td><td>${esc(l.leave_type||'—')}</td><td>${esc(l.start_date)} – ${esc(l.end_date)}</td><td>${l.days}</td><td>${l.document_url?`<span class="text-success">Attached</span>`:'—'}</td><td>${statusPill(l.status)}</td><td><div class="inline-actions"><button class="btn btn-secondary btn-small" data-leave-view="${esc(l.request_id)}">View details</button>${((isManager&&l.status==='Pending Manager Approval')||(!isEmployee&&!isManager&&['Pending HR Approval','Pending Manager Approval'].includes(l.status)))?`<button class="btn btn-secondary btn-small" data-leave="${esc(l.request_id)}" data-decision="Approved">Approve</button><button class="btn btn-danger btn-small" data-leave="${esc(l.request_id)}" data-decision="Rejected">Reject</button>`:''}</div></td></tr>`))+
    tableCard('Leave types','Entitlements and paid/unpaid classification are configurable by HR',['Name','Entitlement days','Paid status'],types.map(t=>`<tr><td>${esc(t.name)}</td><td>${t.entitlement_days===null?'Not configured':t.entitlement_days}</td><td>${esc(t.paid_status)}</td></tr>`))+
    tableCard('Company holidays','Published holiday calendar',['Date','Holiday'],holidays.map(h=>`<tr><td>${esc(h.holiday_date)}</td><td>${esc(h.name)}</td></tr>`));
  $('#applyLeave')?.addEventListener('click',()=>openLeaveForm(types,isEmployee,empOptions));
  $('#addLeaveType')?.addEventListener('click',()=>openLeaveTypeForm());
  $('#addHoliday')?.addEventListener('click',()=>openHolidayForm());
  $$('[data-leave-view]').forEach(b=>b.addEventListener('click',()=>{const item=leaves.find(x=>x.request_id===b.dataset.leaveView);if(item)showLeaveDetails(item);}));
  $$('[data-leave]').forEach(b=>b.addEventListener('click',()=>decideLeave(b.dataset.leave,b.dataset.decision)));
  // HR can create a request on behalf of an employee.
  if(!isEmployee&&!isManager){const h=$('.heading-actions');const b=document.createElement('button');b.className='btn btn-primary';b.textContent='＋ Record leave';b.addEventListener('click',()=>openLeaveForm(types,false,empOptions));h.append(b);}
}
function showLeaveDetails(l){
  const docUrl=l.document_url?`${l.document_url}`:'';
  const docName=l.document_name||'Supporting document';
  const mime=String(l.document_content_type||'').toLowerCase();
  const isImage=mime.startsWith('image/');
  const isPdf=mime==='application/pdf'||String(docName).toLowerCase().endsWith('.pdf');
  const preview=docUrl?(isImage?`<div class="notice"><img src="${esc(docUrl)}" alt="Leave supporting document" style="display:block;max-width:100%;max-height:520px;margin:0 auto;object-fit:contain"></div>`:isPdf?`<iframe title="Leave supporting PDF" src="${esc(docUrl)}" style="width:100%;height:520px;border:1px solid var(--border);border-radius:10px"></iframe>`:`<div class="notice">Preview is not available for this file type. Use Open / Download to inspect it.</div>`):`<div class="notice">No supporting document was attached to this request.</div>`;
  const detail=(label,value)=>`<div class="field"><span>${label}</span><strong>${esc(value||'—')}</strong></div>`;
  const body=`<div class="form-grid">
    ${detail('Request ID',l.request_id)}${detail('Status',l.status)}
    ${detail('Employee',l.full_name||l.employee_id)}${detail('Employee ID',l.employee_id)}
    ${detail('Leave type',l.leave_type||'—')}${detail('Total leave days',`${l.days} day(s)`)}
    ${detail('Start date',l.start_date)}${detail('End date',l.end_date)}
    <div class="field full-span"><span>Reason for leave</span><div class="notice" style="white-space:pre-wrap">${esc(l.reason||'No reason provided')}</div></div>
    <div class="field full-span"><span>Supporting document</span>${docUrl?`<p><strong>${esc(docName)}</strong> <a class="btn btn-secondary btn-small" href="${esc(docUrl)}" target="_blank" rel="noopener">Open</a> <a class="btn btn-secondary btn-small" href="${esc(docUrl)}?download=1" target="_blank" rel="noopener">Download</a></p>${preview}`:preview}</div>
    <div class="field full-span"><span>Manager decision</span><div class="notice">${esc(l.manager_decision||'Not reviewed')} · ${esc(l.manager_comment||'No manager comment')}</div><small class="muted-note">${esc(l.manager_decided_by||'')} ${esc(l.manager_decided_at||'')}</small></div>
    <div class="field full-span"><span>HR decision</span><div class="notice">${esc(l.hr_decision||'Not reviewed')} · ${esc(l.hr_comment||'No HR comment')}</div><small class="muted-note">${esc(l.hr_decided_by||'')} ${esc(l.hr_decided_at||'')}</small></div>
    <div class="field full-span"><span>Submitted</span><strong>${esc(l.created_at||'—')}</strong></div>
  </div>`;
  openInfoModal(`Leave request · ${l.request_id}`,body,()=>{},false,'',true);
}

