async function renderPayroll(){
  const data=await api('/api/payroll');
  const total=data.runs.filter(r=>r.status==='Approved').length;
  $('#pageContent').innerHTML=pageHeader('Payroll & compensation','Private payroll workspace · BDT (৳) · Access restricted to authorized payroll users.',`<button class="btn btn-secondary" id="addSalary">＋ Salary record</button><button class="btn btn-primary" id="createPayroll">Generate monthly preview</button>`)+
    `<div class="notice warning">Attendance-based calculation: (monthly basic salary + fixed allowances) × (present days + approved leave marked Paid) ÷ scheduled working days. Scheduled days follow each employee’s assigned shift, weekly offs and company holidays. Late and absent days are shown; no automatic late penalty, tax or statutory deduction is invented. Configure every employee shift and verify the formula against company policy before approval.</div>`+
    `<div class="metric-grid">${metric('Payroll runs',data.runs.length,'Draft and approved','▤')}${metric('Approved months',total,'Locked payroll periods','✓')}${metric('Salary records',data.salaries.length,'Effective-dated records','৳')}${metric('Currency','BDT','Bangladeshi Taka','◈')}</div>`+
    tableCard('Monthly payroll runs','Review previews and open payroll details',['Pay month','Run ID','Status','Created','Approved by','Actions'],data.runs.map(r=>`<tr><td><strong>${esc(r.pay_month)}</strong></td><td>${esc(r.run_id)}</td><td>${statusPill(r.status)}</td><td>${esc(formatDateTime(r.created_at))}</td><td>${esc(r.approved_by||'—')}</td><td><button class="btn btn-secondary btn-small" data-payrun="${r.run_id}">Open</button></td></tr>`))+
    tableCard('Effective salary records','Visible only to authorized payroll roles',['Employee','Effective from','Basic salary','Fixed allowances','Notes'],data.salaries.map(s=>`<tr><td>${person(s.full_name,s.employee_id)}</td><td>${esc(s.effective_from)}</td><td>${money(s.basic_salary)}</td><td>${money(s.fixed_allowances)}</td><td>${esc(s.notes||'—')}</td></tr>`));
  $('#addSalary').addEventListener('click',()=>openSalaryForm());
  $('#createPayroll').addEventListener('click',()=>openPayrollPreviewForm());
  $$('[data-payrun]').forEach(b=>b.addEventListener('click',()=>openPayrollRun(b.dataset.payrun)));
}
async function openSalaryForm(){const employees=await api('/api/payroll/employees');const opts='<option value="">Select employee</option>'+employees.map(e=>`<option value="${e.employee_id}">${esc(e.employee_id)} · ${esc(e.full_name)}</option>`).join('');openModal('Add salary record',`<form id="modalForm" class="form-grid">${field('Employee','employee_id','select',true,opts)}${field('Effective from','effective_from','date',true,today())}${field('Basic salary (৳)','basic_salary','number',true,'','0.00')}${field('Fixed allowances (৳)','fixed_allowances','number',false,'','0.00')}${field('Notes','notes','textarea',false,'','Policy reference or approval details',true)}</form>`,async f=>{await post('/api/payroll/salary',formToJSON(f));closeModal();toast('Salary record saved');await renderPayroll();});}
function openPayrollPreviewForm(){openModal('Generate payroll preview',`<form id="modalForm" class="form-grid">${field('Pay month','pay_month','month',true,today().slice(0,7))}<div class="field full-span"><span class="muted-note">This creates a draft preview for active, probation and on-notice employees. No email is sent and no payslip is issued.</span></div></form>`,async f=>{const res=await post('/api/payroll/preview',formToJSON(f));closeModal();toast('Payroll preview created');await renderPayroll();await openPayrollRun(res.run_id);});}
async function openPayrollRun(runId){const data=await api('/api/payroll/run/'+runId);state.payrollRun=data.run;state.payrollItems=data.items;const approved=data.run.status==='Approved';openInfoModal(`Payroll · ${data.run.pay_month}`,`<div class="notice ${approved?'success':'warning'}">Status: ${esc(data.run.status)}. ${approved?'This payroll is locked.':'Review amounts carefully. Use Adjust to enter approved variable earnings and deductions.'}</div><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Scheduled</th><th>Present</th><th>Late</th><th>Absent</th><th>Paid leave</th><th>Payable</th><th>Basic</th><th>Allowances</th><th>Overtime</th><th>Bonus</th><th>Deductions</th><th>Net pay</th>${approved?'':'<th>Action</th>'}</tr></thead><tbody>${data.items.map(i=>`<tr><td>${person(i.full_name,i.employee_id)}<small style="display:block;color:#9aa7ae">${esc(i.calculation_status||'—')}</small></td><td>${i.scheduled_days??'—'}</td><td>${i.present_days??'—'}</td><td>${i.late_days??'—'}</td><td>${i.absent_days??'—'}</td><td>${i.paid_leave_days??'—'}</td><td>${i.payable_days??'—'}</td><td>${money(i.basic_salary)}</td><td>${money(i.allowances)}</td><td>${money(i.overtime)}</td><td>${money(i.bonus)}</td><td>${money(i.deductions+i.adjustments)}</td><td><strong>${money(i.net_salary)}</strong></td>${approved?'':`<td><button class="btn btn-secondary btn-small" data-edit-pay="${i.employee_id}">Adjust</button></td>`}</tr>`).join('')}</tbody></table></div><div class="notice">Monthly fixed compensation is prorated by payable attendance days. Payable days = present days + approved Paid leave. Late days are informational only unless an authorized company policy and approved deduction are entered separately.</div>`,async()=>{if(!approved){if(!confirm('Approve and lock this payroll month?'))return;await post(`/api/payroll/run/${runId}/approve`,{});toast('Payroll approved and locked');closeModal();await renderPayroll();}},!approved,'',true);
  $$('[data-edit-pay]').forEach(b=>b.addEventListener('click',()=>openPayrollItemForm(runId,data.items.find(x=>x.employee_id===b.dataset.editPay))));
}
function openPayrollItemForm(runId,item){openModal(`Adjust payroll · ${item.full_name}`,`<form id="modalForm" class="form-grid">${field('Employee','employee_id','text',true,item.employee_id)}${field('Approved overtime (৳)','overtime','number',false,String(item.overtime))}${field('Approved bonus (৳)','bonus','number',false,String(item.bonus))}${field('Approved deductions (৳)','deductions','number',false,String(item.deductions))}${field('Other approved adjustments (৳)','adjustments','number',false,String(item.adjustments))}${field('Notes','notes','textarea',false,'','Approval reference',true)}</form>`,async f=>{const v=formToJSON(f);await post(`/api/payroll/run/${runId}/items`,v);closeModal();toast('Payroll item updated');await openPayrollRun(runId);});}

async function renderMyPayslips(){const slips=await api('/api/my-payslips');$('#pageContent').innerHTML=pageHeader('My payslips','Only approved payroll periods are visible in employee self-service.')+tableCard('Approved payslips','Your private compensation history',['Pay month','Basic','Allowances','Overtime','Bonus','Deductions','Net salary','Action'],slips.map(s=>`<tr><td>${esc(s.pay_month)}</td><td>${money(s.basic_salary)}</td><td>${money(s.allowances)}</td><td>${money(s.overtime)}</td><td>${money(s.bonus)}</td><td>${money(s.deductions+s.adjustments)}</td><td><strong>${money(s.net_salary)}</strong></td><td><button class="btn btn-secondary btn-small" data-print-slip="${s.pay_month}">Print</button></td></tr>`));$$('[data-print-slip]').forEach(b=>b.addEventListener('click',()=>{const s=slips.find(x=>x.pay_month===b.dataset.printSlip);printPayslip(s);}));}
function printPayslip(s){const w=window.open('','_blank','width=750,height=850');if(!w){toast('Allow pop-ups to print this payslip','error');return;}w.document.write(`<html><head><title>Payslip ${esc(s.pay_month)}</title><style>body{font:14px Arial;padding:35px;color:#1f3440}h1{font-size:22px;color:#023951}table{width:100%;border-collapse:collapse;margin-top:24px}td{padding:12px;border-bottom:1px solid #ddd}.amount{text-align:right;font-weight:bold}.net{font-size:18px;color:#023951}</style></head><body><h1>Salary Payslip</h1><p>Pay period: ${esc(s.pay_month)}<br>Employee ID: ${esc(state.user.employee_id)}<br>Employee: ${esc(state.employee?.full_name||state.user.username)}</p><table><tr><td>Basic salary</td><td class="amount">${money(s.basic_salary)}</td></tr><tr><td>Allowances</td><td class="amount">${money(s.allowances)}</td></tr><tr><td>Overtime</td><td class="amount">${money(s.overtime)}</td></tr><tr><td>Bonus</td><td class="amount">${money(s.bonus)}</td></tr><tr><td>Gross salary</td><td class="amount">${money(s.gross_salary)}</td></tr><tr><td>Deductions & adjustments</td><td class="amount">${money(s.deductions+s.adjustments)}</td></tr><tr><td class="net">Net salary</td><td class="amount net">${money(s.net_salary)}</td></tr></table><p style="margin-top:40px;color:#888;font-size:11px">Private employee document. Generated from the Light Retouch HRMS.</p></body></html>`);w.document.close();w.focus();w.print();}

async function renderRecruitment(){const [rows,positions]=await Promise.all([api('/api/recruitment'),api('/api/recruitment/positions')]);const stages=['Applied','Shortlisted','Interview Scheduled','Interviewed','Selected','Offer Sent','Offer Accepted','Joined','Rejected','Withdrawn','On Hold'];$('#pageContent').innerHTML=pageHeader('Recruitment pipeline','Track candidates through configurable recruitment positions.',`<button class="btn btn-secondary" id="managePositions">Manage positions</button><button class="btn btn-primary" id="addCandidate">＋ Add candidate</button>`)+tableCard('Candidate database',`${rows.length} candidate record${rows.length===1?'':'s'}`,['Candidate','Position','Source','Interview date','Stage','Update stage','Actions'],rows.map(c=>`<tr><td>${person(c.full_name,c.candidate_id+' · '+(c.email||'No email'))}</td><td>${esc(c.position)}</td><td>${esc(c.source||'—')}</td><td>${esc(c.interview_date||'—')}</td><td>${statusPill(c.stage)}</td><td><select class="action-select" data-candidate="${c.candidate_id}">${stages.map(s=>`<option ${s===c.stage?'selected':''}>${s}</option>`).join('')}</select></td><td><div class="inline-actions"><button class="btn btn-secondary btn-small" data-edit-candidate="${c.candidate_id}">Edit</button><button class="btn btn-danger btn-small" data-delete-candidate="${c.candidate_id}">Delete</button></div></td></tr>`));$('#addCandidate').addEventListener('click',()=>openCandidateForm(positions));$('#managePositions').addEventListener('click',()=>openPositionManager(positions));$$('[data-candidate]').forEach(sel=>sel.addEventListener('change',async()=>{try{await post(`/api/recruitment/${sel.dataset.candidate}/stage`,{stage:sel.value});toast('Candidate stage updated');}catch(e){toast(e.message,'error');}}));$$('[data-edit-candidate]').forEach(b=>b.addEventListener('click',()=>openCandidateForm(positions,rows.find(x=>x.candidate_id===b.dataset.editCandidate))));$$('[data-delete-candidate]').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Archive this candidate and preserve the recruitment history?'))return;try{await post(`/api/recruitment/${b.dataset.deleteCandidate}/delete`,{});toast('Candidate archived');await renderRecruitment();}catch(e){toast(e.message,'error');}}));}
async function openCandidateForm(positions,row=null){const positionOpts='<option value="">Select position</option>'+positions.map(p=>`<option value="${esc(p.name)}" ${row?.position===p.name?'selected':''}>${esc(p.name)}${p.name.endsWith('(Demo)')?' · Demo':''}</option>`).join('');const stageList=['Applied','Shortlisted','Interview Scheduled','Interviewed','Selected','Offer Sent','Offer Accepted','Joined','Rejected','Withdrawn','On Hold'];openModal(row?'Edit candidate':'Add candidate',`<form id="modalForm" class="form-grid">${field('Full name','full_name','text',true,row?.full_name||'')}${field('Position','position','select',true,positionOpts)}${field('Email','email','email',false,row?.email||'')}${field('Phone','phone','tel',false,row?.phone||'')}${field('Source','source','text',false,row?.source||'')}${field('Stage','stage','select',true,options(stageList))}${field('Interview date','interview_date','date',false,row?.interview_date||'')}${field('Notes','notes','textarea',false,row?.notes||'','Experience, evaluation notes, next steps',true)}</form>`,async f=>{await post(row?`/api/recruitment/${row.candidate_id}/update`:'/api/recruitment',formToJSON(f));closeModal();toast(row?'Candidate updated':'Candidate added');await renderRecruitment();});if(row)$('#modalForm').elements.stage.value=row.stage;}
function openPositionManager(positions){const rows=positions.map(p=>`<div class="quick-row"><span class="quick-dot"></span><div><strong>${esc(p.name)}</strong><small>${p.name.endsWith('(Demo)')?'Demo entry':'Company position'}</small></div><div class="inline-actions"><button class="btn btn-secondary btn-small" data-edit-position="${p.id}">Edit</button><button class="btn btn-danger btn-small" data-delete-position="${p.id}">Delete</button></div></div>`).join('');openInfoModal('Recruitment positions',`<div class="panel-head"><p>These values appear in the Recruitment Position dropdown.</p><button class="btn btn-primary btn-small" id="addPosition">＋ Add position</button></div>${rows||emptyState('No positions','Add a recruitment position.')}`,()=>{},false,'',true);$('#addPosition').addEventListener('click',()=>openPositionForm());$$('[data-edit-position]').forEach(b=>b.addEventListener('click',()=>openPositionForm(positions.find(x=>String(x.id)===b.dataset.editPosition))));$$('[data-delete-position]').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Archive this position from dropdown choices?'))return;try{await post(`/api/recruitment/positions/${b.dataset.deletePosition}/delete`,{});toast('Position archived');closeModal();await renderRecruitment();}catch(e){toast(e.message,'error');}}));}
function openPositionForm(row=null){openModal(row?'Edit recruitment position':'Add recruitment position',`<form id="modalForm" class="form-grid">${field('Position title','name','text',true,row?.name||'')}</form>`,async f=>{await post(row?`/api/recruitment/positions/${row.id}/update`:'/api/recruitment/positions',formToJSON(f));closeModal();toast(row?'Position updated':'Position added');await renderRecruitment();});}

async function renderPerformance(){const rows=await api('/api/performance');const people=state.cache.employees||await api('/api/employees');const optionsEmp='<option value="">Select employee</option>'+people.map(e=>`<option value="${e.employee_id}">${esc(e.employee_id)} · ${esc(e.full_name)}</option>`).join('');$('#pageContent').innerHTML=pageHeader('Performance management','Record review periods, feedback and goals. Department KPIs and scoring remain company-configurable.',`<button class="btn btn-primary" id="addReview">＋ New review</button>`)+`<div class="notice">Review information is confidential. Manager accounts can only create and view reviews for their direct reports. Do not treat a score as an automatic salary or disciplinary decision.</div>`+tableCard('Review history',`${rows.length} performance record${rows.length===1?'':'s'}`,['Employee','Review period','Type','Score','Reviewer','Status','Actions'],rows.map(r=>`<tr><td>${person(r.full_name,r.employee_id)}</td><td>${esc(r.review_period)}</td><td>${esc(r.review_type)}</td><td>${r.score===null?'—':esc(r.score)}</td><td>${esc(r.reviewer)}</td><td>${statusPill(r.status)}</td><td><div class="inline-actions"><button class="btn btn-secondary btn-small" data-edit-review="${r.review_id}">Edit</button><button class="btn btn-danger btn-small" data-delete-review="${r.review_id}">Delete</button></div></td></tr>`));$('#addReview').addEventListener('click',()=>openReviewForm(optionsEmp));$$('[data-edit-review]').forEach(b=>b.addEventListener('click',()=>openReviewForm(optionsEmp,rows.find(x=>x.review_id===b.dataset.editReview))));$$('[data-delete-review]').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Archive this review and keep its history?'))return;try{await post(`/api/performance/${b.dataset.deleteReview}/delete`,{});toast('Review archived');await renderPerformance();}catch(e){toast(e.message,'error');}}));}
function openReviewForm(empOptions,row=null){openModal(row?'Edit performance review':'Create performance review',`<form id="modalForm" class="form-grid">${field('Employee','employee_id','select',true,empOptions)}${field('Review period','review_period','text',true,row?.review_period||'','e.g. Q4 2026')}${field('Review type','review_type','select',true,options(['Monthly','Quarterly','Annual','Probation']))}${field('Score','score','number',false,row?.score??'','Optional; use approved scorecard')}${field('Feedback','feedback','textarea',false,row?.feedback||'','Reviewer feedback',true)}${field('Goals / improvement plan','goals','textarea',false,row?.goals||'','Agreed next steps',true)}${field('Status','status','select',true,options(['Draft','Submitted','Completed']))}</form>`,async f=>{const v=formToJSON(f);await post(row?`/api/performance/${row.review_id}/update`:'/api/performance',v);closeModal();toast(row?'Review updated':'Review created');await renderPerformance();});if(row){const f=$('#modalForm');f.elements.employee_id.value=row.employee_id;f.elements.employee_id.disabled=true;f.elements.review_type.value=row.review_type;f.elements.status.value=row.status;}}
async function renderAssets(){const rows=await api('/api/assets');$('#pageContent').innerHTML=pageHeader('Asset management','Track company equipment, assignments and returns.',`<button class="btn btn-primary" id="addAsset">＋ Add asset</button>`)+tableCard('Asset register',`${rows.length} asset record${rows.length===1?'':'s'}`,['Asset','Category','Serial number','Assigned to','Assigned date','Condition','Return date','Actions'],rows.map(a=>`<tr><td><strong>${esc(a.asset_name)}</strong><small style="display:block;color:#9aa7ae;margin-top:3px">${esc(a.asset_id)}</small></td><td>${esc(a.category||'—')}</td><td>${esc(a.serial_number||'—')}</td><td>${esc(a.assigned_name||'Unassigned')}</td><td>${esc(a.assignment_date||'—')}</td><td>${statusPill(a.condition_status)}</td><td>${esc(a.return_date||'—')}</td><td><div class="inline-actions"><button class="btn btn-secondary btn-small" data-edit-asset="${a.asset_id}">Edit</button><button class="btn btn-danger btn-small" data-delete-asset="${a.asset_id}">Delete</button></div></td></tr>`));$('#addAsset').addEventListener('click',()=>openAssetForm());$$('[data-edit-asset]').forEach(b=>b.addEventListener('click',()=>openAssetForm(rows.find(x=>x.asset_id===b.dataset.editAsset))));$$('[data-delete-asset]').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Archive this asset record?'))return;try{await post(`/api/assets/${b.dataset.deleteAsset}/delete`,{});toast('Asset archived');await renderAssets();}catch(e){toast(e.message,'error');}}));}
function openAssetForm(row=null){const people=state.cache.employees||[];const opts='<option value="">Unassigned</option>'+people.map(e=>`<option value="${e.employee_id}" ${row?.assigned_employee===e.employee_id?'selected':''}>${esc(e.employee_id)} · ${esc(e.full_name)}</option>`).join('');openModal(row?'Update company asset':'Register company asset',`<form id="modalForm" class="form-grid">${field('Asset name','asset_name','text',true,row?.asset_name||'')}${field('Category','category','text',false,row?.category||'')}${field('Serial number','serial_number','text',false,row?.serial_number||'')}${field('Purchase date','purchase_date','date',false,row?.purchase_date||'')}${field('Assign to','assigned_employee','select',false,opts)}${field('Assignment date','assignment_date','date',false,row?.assignment_date||'')}${field('Condition','condition_status','select',true,options(['Good','Fair','Needs repair','Damaged']))}${field('Return date','return_date','date',false,row?.return_date||'')}${field('Return condition','return_condition','text',false,row?.return_condition||'')}${field('Notes','notes','textarea',false,row?.notes||'','Asset details',true)}</form>`,async f=>{await post(row?`/api/assets/${row.asset_id}/update`:'/api/assets',formToJSON(f));closeModal();toast(row?'Asset updated':'Asset registered');await renderAssets();});if(row)$('#modalForm').elements.condition_status.value=row.condition_status;}
async function renderRelations(){const rows=await api('/api/disciplinary');$('#pageContent').innerHTML=pageHeader('Employee relations','Keep a confidential, factual record of employee relations and disciplinary processes.',`<button class="btn btn-primary" id="addDiscipline">＋ New record</button>`)+`<div class="notice warning">This module records information only. It does not automatically impose penalties, salary deductions or employment decisions. All outcomes require authorized human review and documented process.</div>`+tableCard('Disciplinary index',`${rows.length} record${rows.length===1?'':'s'}`,['Record','Employee','Type','Incident date','Description','Decision','Follow-up','Actions'],rows.map(r=>`<tr><td>${esc(r.record_id)}</td><td>${person(r.full_name,r.employee_id)}</td><td>${esc(r.record_type)}</td><td>${esc(r.incident_date)}</td><td>${esc(r.description)}</td><td>${statusPill(r.decision)}</td><td>${esc(r.follow_up_date||'—')}</td><td><div class="inline-actions"><button class="btn btn-secondary btn-small" data-edit-discipline="${r.record_id}">Edit</button><button class="btn btn-danger btn-small" data-delete-discipline="${r.record_id}">Delete</button></div></td></tr>`));$('#addDiscipline').addEventListener('click',()=>openDisciplineForm());$$('[data-edit-discipline]').forEach(b=>b.addEventListener('click',()=>openDisciplineForm(rows.find(x=>x.record_id===b.dataset.editDiscipline))));$$('[data-delete-discipline]').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Archive this confidential record?'))return;try{await post(`/api/disciplinary/${b.dataset.deleteDiscipline}/delete`,{});toast('Record archived');await renderRelations();}catch(e){toast(e.message,'error');}}));}
function openDisciplineForm(row=null){const people=state.cache.employees||[];const opts='<option value="">Select employee</option>'+people.map(e=>`<option value="${e.employee_id}" ${row?.employee_id===e.employee_id?'selected':''}>${esc(e.employee_id)} · ${esc(e.full_name)}</option>`).join('');openModal(row?'Edit confidential record':'Create confidential record',`<form id="modalForm" class="form-grid">${field('Employee','employee_id','select',true,opts)}${field('Record type','record_type','select',true,options(['Verbal warning','Written warning','Show-cause notice','Investigation','Employee complaint','Other']))}${field('Incident date','incident_date','date',true,row?.incident_date||'')}${field('Follow-up date','follow_up_date','date',false,row?.follow_up_date||'')}${field('Description','description','textarea',true,row?.description||'','Factual account and supporting details',true)}${field('Employee response','employee_response','textarea',false,row?.employee_response||'','Add response when received',true)}${field('Decision','decision','select',true,options(['Pending Review','No Action','Warning Issued','Further Investigation','Resolved']))}</form>`,async f=>{const v=formToJSON(f);await post(row?`/api/disciplinary/${row.record_id}/update`:'/api/disciplinary',v);closeModal();toast(row?'Record updated':'Confidential record created');await renderRelations();});if(row){const f=$('#modalForm');f.elements.employee_id.disabled=true;f.elements.record_type.value=row.record_type;f.elements.decision.value=row.decision;}}
async function renderExits(){const rows=await api('/api/exits');$('#pageContent').innerHTML=pageHeader('Exit management','Track notice periods, clearance checkpoints and final settlement readiness.',`<button class="btn btn-primary" id="newExit">＋ Start exit checklist</button>`)+tableCard('Exit checklists',`${rows.length} employee exit${rows.length===1?'':'s'}`,['Employee','Exit type','Last working day','Progress','Status','Action'],rows.map(r=>{const keys=['resignation_document','attendance_clearance','leave_clearance','asset_clearance','account_clearance','manager_clearance','hr_clearance','finance_clearance','final_settlement'];const done=keys.filter(k=>r[k]).length;return `<tr><td>${person(r.full_name,r.employee_id)}</td><td>${esc(r.exit_type)}</td><td>${esc(r.last_working_day||'—')}</td><td>${done}/9</td><td>${statusPill(r.status)}</td><td><div class="inline-actions"><button class="btn btn-secondary btn-small" data-exit="${r.exit_id}">Update</button><button class="btn btn-danger btn-small" data-delete-exit="${r.exit_id}">Delete</button></div></td></tr>`;}));$('#newExit').addEventListener('click',()=>openExitForm());$$('[data-exit]').forEach(b=>b.addEventListener('click',()=>openExitUpdate(rows.find(x=>x.exit_id===b.dataset.exit))));$$('[data-delete-exit]').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Archive this exit checklist?'))return;try{await post(`/api/exits/${b.dataset.deleteExit}/delete`,{});toast('Exit record archived');await renderExits();}catch(e){toast(e.message,'error');}}));}
function openExitForm(){const people=state.cache.employees||[];const opts='<option value="">Select employee</option>'+people.map(e=>`<option value="${e.employee_id}">${esc(e.employee_id)} · ${esc(e.full_name)}</option>`).join('');openModal('Start exit checklist',`<form id="modalForm" class="form-grid">${field('Employee','employee_id','select',true,opts)}${field('Exit type','exit_type','select',true,options(['Resignation','Termination','Contract completion','Other']))}${field('Notice start','notice_start','date')}${field('Last working day','last_working_day','date')}${field('Notes','notes','textarea',false,'','Relevant handover notes',true)}</form>`,async f=>{await post('/api/exits',formToJSON(f));closeModal();toast('Exit checklist started');await renderExits();});}
function openExitUpdate(row){const labels={resignation_document:'Resignation / termination documentation',attendance_clearance:'Attendance clearance',leave_clearance:'Leave clearance',asset_clearance:'Company asset return',account_clearance:'Company account and access handover',manager_clearance:'Manager clearance',hr_clearance:'HR clearance',finance_clearance:'Finance clearance',final_settlement:'Final settlement'};const fields=Object.entries(labels).map(([k,l])=>`<label class="check-item"><input type="checkbox" name="${k}" ${row[k]?'checked':''}>${esc(l)}</label>`).join('');openModal(`Exit checklist · ${row.full_name}`,`<form id="modalForm"><div class="checklist">${fields}</div><div style="height:14px"></div>${field('Notes','notes','textarea',false,row.notes||'','Additional clearance notes',true)}</form>`,async f=>{const v=formToJSON(f);Object.keys(labels).forEach(k=>v[k]=f.querySelector(`[name="${k}"]`).checked);await post(`/api/exits/${row.exit_id}/update`,v);closeModal();toast('Exit checklist updated');await renderExits();});}

async function renderSettings(){
  const [settings,deps,designations,shifts,holidays,types,positions]=await Promise.all([api('/api/settings'),api('/api/departments'),api('/api/designations'),api('/api/shifts'),api('/api/holidays'),api('/api/leave-types'),api('/api/recruitment/positions')]);
  state.cache.departments=deps;state.settings=settings;applyBranding();const backups=state.user.role==='super_admin'?await api('/api/backups'):[];
  const masterRows=(entity,arr,details)=>arr.map(x=>`<div class="quick-row"><span class="quick-dot"></span><div><strong>${esc(x.name)}</strong><small>${esc(details(x))}${x.is_active===0?' · Archived':''}</small></div><div class="inline-actions"><button class="btn btn-secondary btn-small" data-master-edit="${entity}" data-id="${x.id}">Edit</button>${x.is_active===0?'':`<button class="btn btn-danger btn-small" data-master-delete="${entity}" data-id="${x.id}">Delete</button>`}</div></div>`).join('');
  $('#pageContent').innerHTML=pageHeader('System settings','Customize system identity, logo and editable master data. Demo entries are supplied so you can revise them later.',`<button class="btn btn-primary" id="saveSettings">Save configuration</button>`)+
  `<div class="settings-grid"><div class="settings-card"><h3>System branding</h3><p>Set the name shown in the browser, login and application menu.</p><div class="form-grid">${field('System name','system_name','text',true,settings.system_name||'Light Retouch Management System')}${field('Company name','company_name','text',true,settings.company_name||'Light Retouch')}${field('Work location','work_location','text',false,settings.work_location)}${field('Timezone','timezone','text',true,settings.timezone||'Asia/Dhaka')}${field('Currency','currency','text',true,settings.currency||'BDT')}<label class="field full-span"><span>Company logo (PNG, JPG or WEBP · max 2 MB)</span><input type="file" id="brandLogoFile" accept=".png,.jpg,.jpeg,.webp"></label><div class="field full-span"><img src="/brand-logo" onerror="this.style.display='none'" alt="Current logo" style="max-width:180px;max-height:80px;object-fit:contain"></div></div></div>
  <div class="settings-card"><h3>Attendance & payroll rules</h3><p>Do not enter a policy value without management approval.</p><div class="form-grid">${field('Attendance grace minutes','attendance_grace_minutes','number',false,settings.attendance_grace_minutes,'Leave blank until approved')}${field('Standard working hours','standard_working_hours','number',false,settings.standard_working_hours,'Not configured')}${field('Payroll day','payroll_day','number',false,settings.payroll_day,'Not configured')}${field('Leave year start','leave_year_start','text',false,settings.leave_year_start,'YYYY-MM-DD')}${field('Policy note','policy_note','textarea',false,settings.policy_note,'',true)}</div></div>
  <div class="settings-card"><div class="panel-head"><div><h3>Departments</h3><p>Demo values can be edited or removed.</p></div><button class="btn btn-secondary btn-small" id="addDepartment">＋ Add</button></div>${masterRows('departments',deps,x=>x.description||'Department')}</div>
  <div class="settings-card"><div class="panel-head"><div><h3>Designations</h3><p>Job title master list</p></div><button class="btn btn-secondary btn-small" id="addDesignation">＋ Add</button></div>${masterRows('designations',designations,x=>x.department||x.description||'All departments')}</div>
  <div class="settings-card"><div class="panel-head"><div><h3>Shift master</h3><p>Demo timings are editable—confirm actual policy before payroll use.</p></div><button class="btn btn-secondary btn-small" id="addShift">＋ Add</button></div>${masterRows('shifts',shifts,x=>`${x.start_time?formatClock(x.start_time):'Not set'} – ${x.end_time?formatClock(x.end_time):'Not set'} · Break ${x.break_minutes??'—'} min · Grace ${x.grace_minutes??'—'} min`)}</div>
  <div class="settings-card"><div class="panel-head"><div><h3>Recruitment positions</h3><p>Dropdown values in recruitment forms</p></div><button class="btn btn-secondary btn-small" id="addPositionSetting">＋ Add</button></div>${masterRows('positions',positions,x=>x.name.endsWith('(Demo)')?'Demo position':'Recruitment position')}</div>
  <div class="settings-card"><div class="panel-head"><div><h3>Leave types</h3><p>Current configurable categories</p></div><button class="btn btn-secondary btn-small" id="addLeaveTypeSetting">＋ Add</button></div>${types.map(t=>`<div class="quick-row"><span class="quick-dot"></span><div><strong>${esc(t.name)}</strong><small>${t.entitlement_days===null?'Entitlement not set':t.entitlement_days+' days'} · ${esc(t.paid_status)}</small></div><div class="inline-actions"><button class="btn btn-secondary btn-small" data-edit-leave-type="${t.id}">Edit</button><button class="btn btn-danger btn-small" data-delete-leave-type="${t.id}">Delete</button></div></div>`).join('')}</div>
  <div class="settings-card"><div class="panel-head"><div><h3>Company holidays</h3><p>Published holidays used in attendance calculations</p></div><button class="btn btn-secondary btn-small" id="addHolidaySetting">＋ Add</button></div>${holidays.map(h=>`<div class="quick-row"><span class="quick-dot"></span><div><strong>${esc(h.name)}</strong><small>${esc(h.holiday_date)}</small></div><div class="inline-actions"><button class="btn btn-secondary btn-small" data-edit-holiday="${h.id}">Edit</button><button class="btn btn-danger btn-small" data-delete-holiday="${h.id}">Delete</button></div></div>`).join('')||emptyState('No holidays','Add company holiday dates.')}</div>
  ${state.user.role==='super_admin'?`<div class="settings-card"><div class="panel-head"><div><h3>Database backup</h3><p>Verified SQLite snapshots stored locally</p></div><button class="btn btn-secondary btn-small" id="createBackup">Create backup</button></div>${backups.length?backups.slice(0,5).map(b=>`<div class="quick-row"><span class="quick-dot"></span><div><strong>${esc(b.filename)}</strong><small>${(b.size/1024/1024).toFixed(2)} MB · ${esc(formatDateTime(b.modified))}</small></div><a class="btn btn-secondary btn-small" href="/api/backup-download/${encodeURIComponent(b.filename)}">Download</a></div>`).join(''):emptyState('No backups yet','Create a verified local database backup.')}</div>`:''}</div>`;
  $('#saveSettings').addEventListener('click',async()=>{const payload={};$$('[data-setting]').forEach(i=>payload[i.dataset.setting]=i.value);try{await post('/api/settings',payload);const file=$('#brandLogoFile').files[0];if(file)await post('/api/settings/logo',{logo:await fileToPayload(file)});const fresh=await api('/api/settings');state.settings=fresh;applyBranding();toast('Configuration saved');await renderSettings();}catch(e){toast(e.message,'error');}});
  $$('[name="system_name"],[name="company_name"],[name="work_location"],[name="timezone"],[name="currency"],[name="attendance_grace_minutes"],[name="standard_working_hours"],[name="payroll_day"],[name="leave_year_start"],[name="policy_note"]').forEach(el=>el.dataset.setting=el.name);
  $('#addDepartment').addEventListener('click',()=>openDepartmentForm());$('#addDesignation').addEventListener('click',()=>openDesignationForm(deps));$('#addShift').addEventListener('click',()=>openShiftForm());$('#addPositionSetting').addEventListener('click',()=>openPositionForm());$('#addLeaveTypeSetting').addEventListener('click',()=>openLeaveTypeForm());$('#addHolidaySetting').addEventListener('click',()=>openHolidayForm());$$('[data-edit-holiday]').forEach(b=>b.addEventListener('click',()=>openHolidayForm(holidays.find(h=>String(h.id)===b.dataset.editHoliday))));$$('[data-delete-holiday]').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Archive this holiday?'))return;try{await post(`/api/holidays/${b.dataset.deleteHoliday}/delete`,{});toast('Holiday archived');await renderSettings();}catch(e){toast(e.message,'error');}}));
  $$('[data-master-edit]').forEach(b=>b.addEventListener('click',()=>openMasterForm(b.dataset.masterEdit,({departments:deps,designations,shifts,positions})[b.dataset.masterEdit].find(x=>String(x.id)===b.dataset.id))));
  $$('[data-master-delete]').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Archive this master value? Historical records are preserved.'))return;try{const endpoint=b.dataset.masterDelete==='positions'?`/api/recruitment/positions/${b.dataset.id}/delete`:`/api/${b.dataset.masterDelete}/${b.dataset.id}/delete`;await post(endpoint,{});toast('Master value archived');await renderSettings();}catch(e){toast(e.message,'error');}}));
  $$('[data-edit-leave-type]').forEach(b=>b.addEventListener('click',()=>openLeaveTypeEditForm(types.find(t=>String(t.id)===b.dataset.editLeaveType))));
  $$('[data-delete-leave-type]').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Archive this leave type?'))return;try{await post(`/api/leave-types/${b.dataset.deleteLeaveType}/delete`,{});toast('Leave type archived');await renderSettings();}catch(e){toast(e.message,'error');}}));
  $('#createBackup')?.addEventListener('click',async()=>{try{const r=await post('/api/backup',{});toast('Backup created and verified');window.location.href=r.download_url;await renderSettings();}catch(e){toast(e.message,'error');}});
}
async function openMasterForm(entity,row){
  if(entity==='positions'){openPositionForm(row);return;}
  const deps=state.cache.departments||await api('/api/departments');
  const depOpts='<option value="">Not linked to department</option>'+deps.filter(d=>d.is_active!==0).map(d=>`<option value="${d.id}" ${String(d.id)===String(row.department_id)?'selected':''}>${esc(d.name)}</option>`).join('');
  const isShift=entity==='shifts';const title=`${row?'Edit':'Add'} ${entity.slice(0,-1)}`;
  let body=`<form id="modalForm" class="form-grid">${field('Name','name','text',true,row.name||'')}`;
  if(entity==='departments')body+=field('Description','description','text',false,row.description||'');
  if(entity==='designations')body+=field('Department','department_id','select',false,depOpts)+field('Description','description','text',false,row.description||'');
  if(isShift){body+=time12Field('Shift start time','start_time',row.start_time||'')+time12Field('Shift end time','end_time',row.end_time||'')+field('Break minutes','break_minutes','number',false,row.break_minutes??'')+`<label class="field"><span>Count break as paid duty?</span><select name="break_is_paid"><option value="0" ${Number(row.break_is_paid||0)===0?'selected':''}>No — deduct break from duty hours</option><option value="1" ${Number(row.break_is_paid||0)===1?'selected':''}>Yes — include break in duty hours</option></select></label>`+field('Grace minutes','grace_minutes','number',false,row.grace_minutes??'')+`<div class="field full-span"><span>Weekly off days</span><div class="checklist">${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].map(d=>`<label class="check-item"><input type="checkbox" name="weekly_off_days" value="${d}" ${(JSON.parse(row.weekly_off_days||'[]')).includes(d)?'checked':''}>${d}</label>`).join('')}</div></div>`;}
  body+='</form>';
  openModal(title,body,async f=>{const v=formToJSON(f);if(isShift)normalize12HourFields(f,v,['start_time','end_time']);if(isShift)v.weekly_off_days=$$('[name="weekly_off_days"]',f).filter(x=>x.checked).map(x=>x.value);await post(row?`/api/${entity}/${row.id}/update`:`/api/${entity}`,v);closeModal();toast(row?'Master value updated':'Master value added');await renderSettings();});
}

function openDepartmentForm(){openModal('Add department',`<form id="modalForm" class="form-grid">${field('Department name','name','text',true)}${field('Description','description','text')}</form>`,async f=>{await post('/api/departments',formToJSON(f));closeModal();toast('Department added');await renderSettings();});}
async function openDesignationForm(deps){const opts='<option value="">Not linked to department</option>'+deps.filter(d=>d.is_active!==0).map(d=>`<option value="${d.id}">${esc(d.name)}</option>`).join('');openModal('Add designation',`<form id="modalForm" class="form-grid">${field('Designation name','name','text',true)}${field('Department','department_id','select',false,opts)}${field('Description','description','text')}</form>`,async f=>{await post('/api/designations',formToJSON(f));closeModal();toast('Designation added');await renderSettings();});}
function openShiftForm(){openModal('Add shift',`<div class="notice">Choose AM or PM explicitly. Example: 07:30 AM to 03:30 PM is 8 hours of presence. If the configured 60-minute break is unpaid, net duty is 7 hours; select paid break only when company policy counts it as paid working time. Overnight times are stored in 24-hour format.</div><form id="modalForm" class="form-grid">${field('Shift name','name','text',true)}${time12Field('Shift start time','start_time')}${time12Field('Shift end time','end_time')}${field('Break minutes','break_minutes','number',false,'','Not set')}<label class="field"><span>Count break as paid duty?</span><select name="break_is_paid"><option value="0" selected>No — deduct break from duty hours</option><option value="1">Yes — include break in duty hours</option></select></label>${field('Grace minutes','grace_minutes','number',false,'','Not set')}<div class="field full-span"><label>Weekly off days</label><div class="checklist">${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].map(d=>`<label class="check-item"><input type="checkbox" name="weekly_off_days" value="${d}">${d}</label>`).join('')}</div></div></form>`,async f=>{const v=formToJSON(f);normalize12HourFields(f,v,['start_time','end_time']);v.weekly_off_days=$$('[name="weekly_off_days"]',f).filter(x=>x.checked).map(x=>x.value);await post('/api/shifts',v);closeModal();toast('Shift created');await renderSettings();});}

async function renderUsers(){const users=await api('/api/users');$('#pageContent').innerHTML=pageHeader('User access','Create, edit, reactivate or deactivate accounts and assign role permissions.',`<button class="btn btn-primary" id="addUser">＋ Create user</button>`)+`<div class="notice warning">Only the Super Admin can manage user access. Employee and Manager accounts must be linked to a permanent Employee ID. Deactivation preserves audit history.</div>`+tableCard('Authorized accounts',`${users.length} user account${users.length===1?'':'s'}`,['Login','Role','Employee ID','Status','Created','Last login','Actions'],users.map(u=>`<tr><td><strong>${esc(u.username)}</strong></td><td>${esc(ROLES_LABEL[u.role]||labelize(u.role))}</td><td>${esc(u.employee_id||'—')}</td><td>${statusPill(u.is_active?'Active':'Inactive')}</td><td>${esc(formatDateTime(u.created_at))}</td><td>${esc(formatDateTime(u.last_login))}</td><td><div class="inline-actions"><button class="btn btn-secondary btn-small" data-edit-user="${u.id}">Edit / Update</button>${u.is_active?`<button class="btn btn-danger btn-small" data-deactivate-user="${u.id}" ${u.username===state.user.username?'disabled':''}>Delete</button>`:''}</div></td></tr>`));$('#addUser').addEventListener('click',()=>openUserForm());$$('[data-edit-user]').forEach(b=>b.addEventListener('click',()=>openUserEditForm(users.find(u=>String(u.id)===b.dataset.editUser))));$$('[data-deactivate-user]').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Deactivate this login account? The employee and historical records will remain.'))return;try{await post(`/api/users/${b.dataset.deactivateUser}/delete`,{});toast('User access deactivated');await renderUsers();}catch(e){toast(e.message,'error');}}));}
const ROLES_LABEL={super_admin:'Super Admin',hr_admin:'HR Admin',hr_executive:'HR Executive',payroll_admin:'Payroll Admin',manager:'Department Manager',employee:'Employee'};
async function userEmployeeOptions(selected=''){const people=await api('/api/employees');return '<option value="">No employee linked (admin roles)</option>'+people.filter(e=>e.employment_status!=='Inactive').map(e=>`<option value="${esc(e.employee_id)}" ${selected===e.employee_id?'selected':''}>${esc(e.employee_id)} · ${esc(e.full_name)}</option>`).join('');}
async function openUserForm(){const opts=await userEmployeeOptions();openModal('Create user account',`<form id="modalForm" class="form-grid">${field('Login email','username','email',true)}${field('Initial password','password','password',true,'','Minimum 12 characters')}${field('Role','role','select',true,options(['super_admin','hr_admin','hr_executive','payroll_admin','manager','employee'],ROLES_LABEL))}${field('Linked Employee ID','employee_id','select',false,opts)}</form>`,async f=>{const v=formToJSON(f);if(['manager','employee'].includes(v.role)&&!v.employee_id)throw new Error('Choose an Employee ID for employee or manager roles');await post('/api/users',v);closeModal();toast('User account created');await renderUsers();});}
async function openUserEditForm(u){const opts=await userEmployeeOptions(u.employee_id||'');openModal(`Edit user account · ${u.username}`,`<form id="modalForm" class="form-grid">${field('Login email','username','email',true,u.username)}${field('Role','role','select',true,options(['super_admin','hr_admin','hr_executive','payroll_admin','manager','employee'],ROLES_LABEL))}${field('Linked Employee ID','employee_id','select',false,opts)}${field('Reset password (optional)','reset_password','password',false,'','Leave blank to keep current password')}<label class="field full-span"><span><input type="checkbox" name="is_active" value="true" ${u.is_active?'checked':''}> Account active</span></label></form>`,async f=>{const v=formToJSON(f);v.is_active=f.elements.is_active.checked;if(['manager','employee'].includes(v.role)&&!v.employee_id)throw new Error('Choose an Employee ID for employee or manager roles');await post(`/api/users/${u.id}/update`,v);closeModal();toast('User access updated');await renderUsers();});const f=$('#modalForm');f.elements.role.value=u.role;}

async function renderAudit(){const rows=await api('/api/audit');$('#pageContent').innerHTML=pageHeader('Audit trail','Recent account, HR and payroll actions recorded by the application.')+tableCard('System activity','Latest 500 events',['Date & time','Actor','Action','Record type','Record ID','Details'],rows.map(r=>`<tr><td>${esc(formatDateTime(r.created_at))}</td><td>${esc(r.actor)}</td><td>${esc(r.action)}</td><td>${esc(r.entity)}</td><td>${esc(r.entity_id||'—')}</td><td>${esc(r.details||'—')}</td></tr>`));}

const ROLES_UNUSED={};
function options(values, labels={}) {return values.map(v=>`<option value="${esc(v)}">${esc(labels[v]||v)}</option>`).join('');}
function field(label,name,type='text',required=false,extra='',placeholder='',full=false){let control='';if(type==='select'){control=`<select name="${esc(name)}" ${required?'required':''}>${extra}</select>`;}else if(type==='textarea'){control=`<textarea name="${esc(name)}" placeholder="${esc(placeholder)}" ${required?'required':''}>${esc(extra||'')}</textarea>`;}else{const value=(extra!==''&&extra!==null&&extra!==undefined&&type!=='password')?`value="${esc(extra)}"`:'';control=`<input type="${esc(type)}" name="${esc(name)}" ${value} placeholder="${esc(placeholder||((type==='date'||type==='month')?'': ''))}" ${required?'required':''} ${type==='number'?'step="0.01" min="0"':''}>`;}return `<label class="field ${full?'full-span':''}"><span>${esc(label)}${required?' *':''}</span>${control}</label>`;}
function formToJSON(form){const obj={};for(const [k,v] of new FormData(form).entries()){if(obj[k]!==undefined){if(!Array.isArray(obj[k]))obj[k]=[obj[k]];obj[k].push(v);}else obj[k]=v;}return obj;}
function openModal(title,body,onSave,wide=false,locked=false){
  $('#modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal ${wide?'wide':''}"><div class="modal-head"><h3>${esc(title)}</h3><button class="modal-close" id="modalClose">×</button></div><div class="modal-body">${body}</div><div class="modal-foot"><button class="btn btn-outline" id="modalCancel">Cancel</button><button class="btn btn-primary" id="modalSave">Save record</button></div></div></div>`;
  $('#modalClose').addEventListener('click',closeModal);$('#modalCancel').addEventListener('click',closeModal);
  $('#modalSave').addEventListener('click',async()=>{const form=$('#modalForm');if(form&&!form.reportValidity())return;const btn=$('#modalSave');btn.disabled=true;btn.textContent='Saving…';try{await onSave(form||document.createElement('form'));}catch(e){toast(e.message,'error');btn.disabled=false;btn.textContent='Save record';}});
  if(!locked) $('.modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal();});
}
function openInfoModal(title,body,onPrimary=()=>{},showPrimary=false,copyText='',wide=false){
  $('#modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal ${wide?'wide':''}"><div class="modal-head"><h3>${esc(title)}</h3><button class="modal-close" id="modalClose">×</button></div><div class="modal-body">${body}</div><div class="modal-foot">${copyText?'<button class="btn btn-secondary" id="copyInfo">Copy</button>':''}<button class="btn btn-outline" id="modalCancel">Close</button>${showPrimary?'<button class="btn btn-primary" id="modalPrimary">Approve & lock</button>':''}</div></div></div>`;
  $('#modalClose').addEventListener('click',closeModal);$('#modalCancel').addEventListener('click',closeModal);if(showPrimary)$('#modalPrimary').addEventListener('click',onPrimary);if(copyText)$('#copyInfo').addEventListener('click',()=>navigator.clipboard.writeText(copyText).then(()=>toast('Copied to clipboard')).catch(()=>toast('Clipboard access unavailable','error')));
}
function closeModal(){$('#modalRoot').innerHTML='';}
function openChangePassword(mandatory=false){
  openModal(mandatory?'Change temporary password':'Change password',`<div class="notice warning">${mandatory?'Your account was created with a temporary password. Set a new password before continuing.':'Choose a new password with at least 12 characters.'}</div><form id="modalForm" class="form-grid">${field('Current password','current_password','password',true)}${field('New password','new_password','password',true)}${field('Confirm new password','confirm_password','password',true)}</form>`,async f=>{
    const v=formToJSON(f);
    if(v.new_password!==v.confirm_password)throw new Error('New password and confirmation do not match');
    await post('/api/change-password',{current_password:v.current_password,new_password:v.new_password});
    closeModal(); state.user.must_change_password=false; toast('Password updated');
    if(mandatory)await navigate('dashboard');
  },false,mandatory);
  $('#modalCancel').style.display=mandatory?'none':'';
  $('#modalClose').style.display=mandatory?'none':'';
}

$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;const button=$('button[type="submit"]',form);button.disabled=true;button.textContent='Signing in…';try{const res=await post('/api/login',formToJSON(form));state.user=res.user;const me=await api('/api/me');state.user=me.user;state.employee=me.employee;state.settings=me.settings||{};showApp();setUserChrome();renderNav();if(state.user.must_change_password)openChangePassword(true);else await navigate('dashboard');}catch(err){showLogin(err.message);}finally{button.disabled=false;button.innerHTML='Sign in <span>→</span>';}});
$('.password-toggle').addEventListener('click',()=>{const input=$('input[name="password"]');const show=input.type==='password';input.type=show?'text':'password';$('.password-toggle').textContent=show?'Hide':'Show';});
$('#logoutBtn').addEventListener('click',async()=>{try{await post('/api/logout',{});}catch{}state.user=null;state.employee=null;showLogin();});
$('#changePasswordBtn').addEventListener('click',()=>openChangePassword(false));
$('#topAvatar').addEventListener('click',()=>openChangePassword(false));
$('#menuToggle').addEventListener('click',()=>{$('#sidebar').classList.add('open');$('#sidebarScrim').classList.add('show');});
$('#closeSidebar').addEventListener('click',closeSidebar);$('#sidebarScrim').addEventListener('click',closeSidebar);
function closeSidebar(){$('#sidebar').classList.remove('open');$('#sidebarScrim').classList.remove('show');}

document.addEventListener('click',ev=>{if(ev.target.closest('#dashTasks'))navigate('tasks');});
boot();
